{
  "findings": [
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "Access logging is not enabled for the S3 bucket. Without access logging, it is difficult to track access patterns and detect unauthorized access."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "Ensure all data stored in the S3 bucket have versioning enabled",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "Versioning is not enabled for the S3 bucket. Without versioning, it is not possible to recover from accidental deletions or overwrites of objects."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "Ensure that S3 buckets are encrypted with KMS by default",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket is not encrypted with a KMS key. Without encryption, data at rest is vulnerable to unauthorized access."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a Public Access Block configuration. Without this, the bucket could be accidentally exposed to the public."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"flowbucket\" {\n  bucket        = \"${local.resource_prefix.value}-flowlogs\"\n  force_destroy = true\n\n  tags = merge({\n    Name        = \"${local.resource_prefix.value}-flowlogs\"\n    Environment = local.resource_prefix.value\n  }, {})\n\n  logging {\n    target_bucket = \"${local.resource_prefix.value}-log-bucket\"\n    target_prefix = \"${local.resource_prefix.value}/\"\n  }\n\n  versioning {\n    enabled = true\n  }\n\n  server_side_encryption_configuration {\n    rule {\n      apply_server_side_encryption_by_default {\n        kms_master_key_id = \"aws/s3\"\n        sse_algorithm     = \"aws:kms\"\n      }\n    }\n  }\n\n  public_access_block {\n    block_public_acls       = true\n    block_public_policy     = true\n    ignore_public_acls      = true\n    restrict_public_buckets = true\n  }\n}",
  "fix_summary": "Enabled access logging, versioning, KMS encryption, and a public access block for the S3 bucket to enhance security and compliance."
}
